import sys

def divisors(num):
    ret = []
    i = 2
    while i * i < num:
        if num % i == 0:
            ret.append(i)
            ret.append(num // i)
        i += 1
    if i * i == num:
        ret.append(i)
    return ret

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    out_lines = []
    for i in range(0, len(data), 3):
        n = int(data[i])
        m = int(data[i + 1])
        k = int(data[i + 2])
        if n % 2 == 0:
            out_lines.append("Marsel")
            continue
        div = divisors(m)
        if m > 1:
            div.append(1)
        flag = False
        for d in div:
            if d >= k:
                flag = True
                break
        if flag:
            out_lines.append("Timur")
        else:
            out_lines.append("Marsel")
    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    main()

